 if(b.type==='tool_use'){uses[b.id]=b; if(b.name.startsWith('mcp__')) console.log('['+o.timestamp.slice(11,19)+'] '+b.name.replace('mcp__','')+' '+JSON.stringify(b.input).slice(0,250));}
