node -e "
const fs=require('fs');const lines=fs.readFileSync('transcript.jsonl','utf8').split('\n').filter(Boolean);
const uses={};
for(const l of lines){let o;try{o=JSON.parse(l)}catch{continue}
const c=o.message&&o.message.content;if(!Array.isArray(c))continue;
for(const b of c){
 if(b.type==='tool_use')uses[b.id]=b;
 if(b.type==='tool_result'){const u=uses[b.tool_use_id];if(!u||!/Bearer/.test(u.input.command||''))continue;const txt=(typeof b.content==='string'?b.content:JSON.stringify(b.content));
  console.log('=== '+txt.slice(-900)+'\n');}
}}
"

